enum Direction {
  North,
  South,
  East,
  West
}

enum Status {
  Pending = 'PENDING',
  Active = 'ACTIVE',
  Completed = 'COMPLETED',
  Failed = 'FAILED'
}

function getDirectionMessage(dir: Direction): string {
  switch (dir) {
    case Direction.North: return 'Going North';
    case Direction.South: return 'Going South';
    case Direction.East: return 'Going East';
    case Direction.West: return 'Going West';
  }
}

console.log(getDirectionMessage(Direction.North));
console.log(`Direction value: ${Direction.North}`);
console.log(`Status: ${Status.Active}`);
console.log(`All directions: ${Direction.North}, ${Direction.South}, ${Direction.East}, ${Direction.West}`);

